-- Authored extra-learning lessons for the five non-Java subjects.
-- Generated from content/extra-learning-v1/build.py; published rows are immutable.
CREATE TABLE daily_career.extra_learning_catalog (
    slug varchar(80) PRIMARY KEY,
    content_version_id bigint NOT NULL UNIQUE REFERENCES daily_career.learning_content_version(id) ON DELETE RESTRICT,
    display_order smallint NOT NULL UNIQUE CHECK (display_order > 0),
    created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

DO $extra_catalog$
DECLARE
    lesson jsonb;
    question jsonb;
    subject_id bigint;
    content_id bigint;
    content_version_id bigint;
    problem_id bigint;
    problem_version_id bigint;
    question_no integer;
    lesson_no integer := 0;
BEGIN
    FOR lesson IN SELECT value FROM jsonb_array_elements('[{"slug":"spring-change-boundary","subject":"SPRING","subjectName":"Spring Boot","title":"요구사항 변경과 트랜잭션 경계","objective":"기존 서비스 변경에서 검증, DB 변경, 외부 호출의 경계를 구분한다.","keyPoints":["업무 규칙과 저장 경계를 먼저 정한다.","같은 객체 내부 호출에는 기본 프록시 기반 트랜잭션이 적용되지 않을 수 있다.","외부 호출 실패와 DB 롤백은 별도로 설계한다."],"sources":[{"title":"Spring Framework Transaction Propagation","url":"https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/tx-propagation.html"},{"title":"Spring Framework Using @Transactional","url":"https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/annotations.html"}],"body":"# 승인 취소 기능을 안전하게 바꾸기\n\n기존 승인 서비스에 ‘취소 사유를 저장하고, 취소가 확정되면 외부 알림을 보낸다’는 요구가 들어왔다. 먼저 성공 조건을 적는다. 승인 상태와 취소 이력이 함께 저장되어야 하며, 이미 취소된 요청은 상태를 다시 바꾸지 않아야 한다. 알림 전송이 실패해도 어떤 데이터가 남아야 하는지는 업무 담당자와 합의한다. 이 세 가지가 정해지지 않으면 `@Transactional`을 붙이는 위치만 논의해도 정답을 만들 수 없다.\n\n## 입력과 저장 경계\n\nController는 요청 형식과 필수 값을 확인하고, Service는 ‘취소 가능한 상태인가’를 조회한 뒤 상태 변경과 취소 이력을 같은 DB 트랜잭션에서 처리한다. Repository가 각각 커밋하는 구조라면 첫 변경만 반영되는 부분 실패가 생길 수 있다. 상태 확인과 변경 사이에 다른 요청이 끼어들 수 있으므로 필요한 경우 버전 열이나 조건부 UPDATE를 사용하고 영향을 받은 행 수를 확인한다. 취소 ID처럼 재요청을 구별할 키도 저장소 제약과 함께 검토한다.\n\n```java\n@Transactional\npublic CancelResult cancel(long approvalId, String reason) {\n    Approval approval = approvals.findForChange(approvalId);\n    approval.cancel(reason);\n    cancellations.save(approvalId, reason);\n    return new CancelResult(approvalId, approval.status());\n}\n```\n\n이 코드는 개념 예시다. 실제 구현에서는 `approval.cancel`의 상태 규칙, 저장 방식, 예외 처리와 동시 수정 방식을 확인해야 한다. 기본 프록시 방식에서는 같은 객체가 `this.cancel()`을 호출하면 프록시를 거치지 않아 메서드의 트랜잭션 선언이 기대대로 적용되지 않을 수 있다. 호출 경로를 통합 테스트로 확인한다.\n\n## 외부 연계와 검증\n\n원격 알림 API를 DB 트랜잭션 안에서 호출하면 응답 지연 동안 DB 자원을 붙잡고, 원격 성공 뒤 DB 커밋 실패도 일어날 수 있다. 알림의 중요도에 따라 커밋 뒤 발송, 실패 기록과 재처리, 또는 별도 전달 기록을 선택한다. 화면에는 취소 결과와 알림 상태를 혼동하지 않게 표현한다. 정상 취소, 이미 취소됨, 동시 요청, 이력 저장 실패, 알림 실패를 각각 테스트한다. 리뷰에서는 ‘어느 실패가 DB 롤백인가’와 ‘재시도 때 중복 알림이 가능한가’를 설명한다.","questions":[{"prompt":"승인 취소에서 상태 변경은 저장됐지만 취소 이력 저장은 실패했다. 둘이 함께 성립해야 한다는 요구가 있다. 우선 확인할 수정은?","choices":["취소 이력 저장 실패를 무시하고 화면에 성공을 표시한다.","상태와 이력을 하나의 서비스 트랜잭션으로 묶고 실패 시 함께 되돌린다.","Controller에서 두 Repository를 순서대로 호출한다.","이력 저장만 비동기로 바꾸고 성공 응답을 먼저 보낸다."],"answer":2,"explanation":"하나의 업무 결과를 이루는 두 DB 변경은 같은 트랜잭션에서 성공하거나 실패해야 한다. Controller 순서나 비동기 전환만으로 원자성이 생기지 않는다."},{"prompt":"같은 서비스의 `this.cancel()` 호출 경로에서만 트랜잭션 적용이 의심된다. 가장 먼저 할 검증은?","choices":["호출 경로가 Spring 프록시를 통과하는지 확인하고 DB 롤백 통합 테스트를 작성한다.","메서드 이름을 변경하면 프록시가 자동 적용된다고 가정한다.","모든 Repository에 `REQUIRES_NEW`를 붙인다.","Controller에 `synchronized`를 붙여 트랜잭션을 대체한다."],"answer":1,"explanation":"기본 프록시 방식의 내부 호출은 트랜잭션 인터셉터를 지나지 않을 수 있다. 실제 호출 경로와 롤백을 검증한 뒤 경계를 조정한다."},{"prompt":"취소 DB 변경은 성공했으나 외부 알림이 시간 초과됐다. 알림은 재처리해야 하고 취소 상태는 유지해야 한다. 적절한 방향은?","choices":["DB 트랜잭션을 외부 응답이 올 때까지 무기한 유지한다.","알림을 성공한 것으로 기록한다.","취소 커밋과 알림 전달 상태를 구분해 기록하고 실패 건을 재처리한다.","알림 실패 때 이미 커밋된 취소 상태를 화면에서만 숨긴다."],"answer":3,"explanation":"원격 호출의 성공과 DB 커밋은 같은 원자적 작업이 아니다. 전달 상태를 따로 기록해야 실패를 재시도하고 중복을 확인할 수 있다."}],"digest":"c581a89877c6fe0071f90843e73a182d7fa1eb7e2198f5e33f9a5059f7419104"},{"slug":"sql-join-report","subject":"SQL","subjectName":"SQL","title":"조회 조건 변경과 JOIN 결과 검증","objective":"1:N JOIN, 누락 행, 집계 중복을 실제 화면 조회에서 진단한다.","keyPoints":["기준 행과 관계의 개수를 먼저 확인한다.","LEFT JOIN의 오른쪽 조건 위치는 누락 행 보존에 영향을 준다.","집계 전 결과 행을 작은 데이터로 검증한다."],"sources":[{"title":"PostgreSQL 17 Joins Between Tables","url":"https://www.postgresql.org/docs/17/tutorial-join.html"},{"title":"PostgreSQL 17 Using EXPLAIN","url":"https://www.postgresql.org/docs/17/using-explain.html"}],"body":"# 화면의 건수와 합계가 달라졌을 때\n\n주문 목록에 ‘최근 결제 상태’를 추가했더니 화면의 주문 건수가 늘었다. `orders` 한 행에 `payments` 여러 행이 연결되는 1:N 관계인데, 상태를 가져오려고 그대로 JOIN하면 주문이 결제 이력 수만큼 반복된다. 먼저 화면의 기준 행이 주문인지 결제인지 결정하고, 각각의 키와 중복 허용 범위를 적는다. 건수를 맞추려고 `DISTINCT`만 덧붙이면 어떤 결제 상태를 보여줄지 결정되지 않은 문제가 남는다.\n\n## JOIN과 누락 행\n\n결제가 없는 주문도 보여야 한다면 `LEFT JOIN`을 사용할 수 있다. 다만 오른쪽 테이블의 조건을 `WHERE`에 두고 NULL을 제외하면 결제가 없는 주문이 결과에서 사라질 수 있다. 조건이 ‘어떤 결제를 연결할 것인가’인지 ‘전체 주문 중 무엇을 남길 것인가’인지 구분한다.\n\n```sql\nSELECT o.id, p.status\nFROM orders o\nLEFT JOIN payments p\n  ON p.order_id = o.id AND p.current_flag = true\nWHERE o.created_at >= :from_date;\n```\n\n위 쿼리도 주문당 `current_flag = true`인 결제가 둘 이상이면 주문이 중복된다. 따라서 ‘현재 결제는 주문당 하나’라는 업무 불변식을 데이터 제약이나 선택 규칙으로 보장해야 한다. 조회에서 `ROW_NUMBER()`로 하나를 고른다면 같은 시각의 순서까지 결정한다. 잘못된 이력 데이터를 조용히 숨길지 오류로 드러낼지도 합의한다.\n\n## 집계와 성능 확인\n\n목록과 총건수 쿼리에 서로 다른 JOIN 조건을 쓰면 페이지 수와 실제 행이 어긋난다. 작은 테스트 데이터로 결제 0건, 1건, 2건, 현재 표시 2건을 만든 뒤 목록·총건수·금액 합계의 기대값을 먼저 고정한다. 그다음 `EXPLAIN`으로 실행 계획과 예상 행 수를 확인한다. `EXPLAIN ANALYZE`는 실제 실행을 수행하므로 변경 쿼리에서는 운영 데이터에 미치는 영향을 따져야 한다. 인덱스 추가는 조건과 선택도, 쓰기 비용을 보고 결정한다. 리뷰에서는 중복 제거 방식보다 ‘어떤 행이 업무적으로 맞는가’를 먼저 설명한다.","questions":[{"prompt":"주문 1건에 결제 이력 3건이 있다. 목록에 결제 상태를 추가한 뒤 주문이 3줄 보인다. 가장 먼저 확정할 것은?","choices":["화면의 기준 행과 표시할 결제 이력의 선택 규칙","무조건 DISTINCT를 넣을 위치","ORDER BY 제거 여부","페이지 크기를 3배로 늘릴지 여부"],"answer":1,"explanation":"1:N JOIN으로 행이 늘어난 원인을 먼저 모델링해야 한다. 기준 행과 대표 이력 규칙 없이 DISTINCT를 쓰면 상태 선택이 불명확하다."},{"prompt":"결제 없는 주문도 목록에 보여야 하는데 `LEFT JOIN payments p ... WHERE p.status = ''PAID''` 뒤 사라졌다. 요구가 ‘결제 이력이 있으면 PAID 이력만 연결’이라면 수정 방향은?","choices":["INNER JOIN으로 변경한다.","주문을 복제해 결제 행을 만든다.","`p.status = ''PAID''`를 JOIN의 ON 조건으로 옮기고 중복 가능성을 따로 검사한다.","WHERE 절에 `o.id IS NULL`을 추가한다."],"answer":3,"explanation":"오른쪽 테이블 조건을 WHERE에 두면 매칭 없는 NULL 확장 행이 걸러질 수 있다. 연결할 행의 조건이면 ON에 두고 대표 이력 규칙을 검증한다."},{"prompt":"목록은 18건인데 총건수는 12건이다. 두 쿼리의 JOIN 조건이 다르다. 우선할 검증은?","choices":["화면에 12만 고정 표시한다.","결제 0·1·여러 건 데이터를 만들어 두 쿼리의 기준 행과 조건을 비교한다.","총건수 쿼리의 인덱스만 추가한다.","LIMIT 값을 줄여 두 숫자를 비슷하게 만든다."],"answer":2,"explanation":"목록과 건수는 같은 업무 집합을 세야 한다. 관계 수별 테스트 데이터로 조건 차이를 재현한 뒤 수정한다."}],"digest":"fbf0004252886f7d1cb1ae9c9e667fc85a8c1e098da6b575bc2389dfadb0f67f"},{"slug":"algorithm-batch-dedup","subject":"ALGORITHM","subjectName":"알고리즘","title":"배치 중복 제거와 자료구조 선택","objective":"입력 순서와 중복 규칙을 유지하며 배치 데이터를 처리한다.","keyPoints":["중복의 기준 키와 남길 행을 먼저 정한다.","순서가 요구사항이면 순서를 보장하는 자료구조를 선택한다.","복잡도와 메모리 한계를 입력 크기로 검증한다."],"sources":[{"title":"Java 21 LinkedHashMap","url":"https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/util/LinkedHashMap.html"},{"title":"Java 21 HashMap","url":"https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/util/HashMap.html"}],"body":"# 중복 행을 지우기 전에 규칙부터 정하기\n\n외부 기관에서 받은 파일을 배치로 읽는다. 같은 업무 ID가 여러 번 나오며 ‘처음 나온 정상 행을 남기고 원본 순서를 유지한다’는 요구가 있다. 여기서 핵심은 자료구조 이름을 외우는 일이 아니라, 중복 키가 무엇인지와 잘못된 행을 언제 제외할지 정하는 일이다. 파일의 행 번호, 업무 ID, 검증 결과를 작은 표로 만들고 처음 정상 행과 처음 등장한 행이 다를 수 있음을 확인한다.\n\n## 선택할 자료구조\n\n매번 이전 결과 목록을 선형 검색하면 입력이 커질수록 비교 횟수가 크게 늘어난다. 키의 중복 확인에는 Map을 쓸 수 있다. 결과 순서를 처음 채택한 행의 순서로 유지하려면 삽입 순서를 보장하는 `LinkedHashMap`이 맞다. `HashMap`의 순회 순서를 파일 순서라고 가정하지 않는다. 키 객체를 만들 때는 기관 코드와 업무 ID가 함께 식별자인지 결정하고 `equals`·`hashCode`가 같은 기준을 사용하게 한다.\n\n```java\nMap<Key, Row> accepted = new LinkedHashMap<>();\nfor (Row row : rows) {\n    if (!valid(row)) continue;\n    accepted.putIfAbsent(new Key(row.partnerCode(), row.businessId()), row);\n}\nList<Row> result = new ArrayList<>(accepted.values());\n```\n\n이 코드는 ‘검증을 통과한 첫 행’을 남긴다. 요구가 ‘가장 최근 수정 시각의 정상 행’으로 바뀌면 `putIfAbsent`만으로는 맞지 않는다. 비교 기준과 동률 처리, 최종 정렬을 다시 설계해야 한다. 입력 순서가 재처리 때마다 달라지는 파일이라면 결과가 같아야 하는지부터 정한다.\n\n## 배치 크기와 테스트\n\nMap은 선택한 행을 메모리에 보관하므로 파일이 매우 크면 전체 적재 대신 청크, 임시 테이블, DB 제약을 검토한다. 청크를 나누면 같은 키가 다른 청크에 나올 때 중복이 다시 생길 수 있어 전역 판정 위치가 필요하다. 테스트에는 빈 파일, 전부 무효, 첫 행 무효·다음 행 정상, 기관 코드가 다른 동일 업무 ID, 동률, 큰 입력을 넣는다. 성능은 실제 예상 건수에서 측정하고, 작은 샘플의 빠른 실행만으로 운영 배치를 보증하지 않는다.","questions":[{"prompt":"파일 순서대로 첫 정상 행을 남기라는 요구가 있다. 중복 키를 처리한 뒤 결과 순서가 실행마다 달라졌다. 적절한 수정은?","choices":["HashMap의 현재 순서를 문서에 기대값으로 적는다.","LinkedHashMap으로 채택 순서를 보존하고 키 동등성 테스트를 추가한다.","모든 행을 무조건 문자열로 정렬한다.","중복 행이 있어도 결과를 그대로 출력한다."],"answer":2,"explanation":"요구는 채택된 행의 입력 순서 보존이다. LinkedHashMap의 삽입 순서 계약을 사용하고 중복 키가 올바르게 정의됐는지 확인한다."},{"prompt":"기관 코드가 다른 두 행에 같은 업무 ID가 있다. 현재 Map 키는 업무 ID뿐이라 한 행이 사라졌다. 먼저 바꿀 것은?","choices":["기관 코드와 업무 ID가 함께 식별자인지 확인하고 키에 반영한다.","Map 크기를 두 배로 늘린다.","모든 업무 ID 앞에 임의의 숫자를 붙인다.","중복 제거를 삭제하고 오류를 무시한다."],"answer":1,"explanation":"중복 기준이 업무 의미와 달라 데이터가 누락됐다. 용량을 늘려도 키의 의미는 바뀌지 않는다."},{"prompt":"파일을 청크로 나눠 처리하자 서로 다른 청크의 중복 업무 ID가 모두 저장됐다. 재처리까지 고려한 대응은?","choices":["청크 안에서만 중복이면 충분하다고 간주한다.","마지막 청크 결과만 남긴다.","전역 중복 판정 위치와 저장소 제약을 정하고 재처리 테스트를 만든다.","배치 로그를 삭제한다."],"answer":3,"explanation":"청크별 Map은 청크 간 중복을 알 수 없다. 전체 작업 범위에서 키를 판정하고 저장 경계에서도 제약을 확인해야 한다."}],"digest":"2708707e1cd8f7213c3dfd26d24e7f0e194972268093acc7a747bcd49da017fe"},{"slug":"finance-amount-retry","subject":"FINANCE","subjectName":"금융 도메인","title":"금액 정밀도와 중복 요청 처리","objective":"금액 표현과 재요청 처리에서 업무 규칙과 저장 제약을 함께 검증한다.","keyPoints":["금액의 통화·소수 자릿수·반올림 시점을 명시한다.","같은 논리 요청의 재전송을 저장된 결과로 구분한다.","상태 변경과 처리 결과를 함께 기록한다."],"sources":[{"title":"Java 21 BigDecimal","url":"https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/math/BigDecimal.html"},{"title":"PostgreSQL 17 Constraints","url":"https://www.postgresql.org/docs/17/ddl-constraints.html"}],"body":"# 금액 변경 요청이 두 번 들어왔을 때\n\n금액 조정 API의 응답이 늦어 호출자가 같은 요청을 다시 보냈다. 두 요청을 모두 반영하면 잔액이나 집계가 달라진다. 먼저 ‘같은 논리 요청’을 무엇으로 식별할지 정한다. 단순히 금액과 사용자 ID가 같다는 이유만으로 중복이라 하면 사용자가 같은 금액을 두 번 요청한 정상 사례를 막을 수 있다. 요청 ID를 사용한다면 누가 발급하고 어느 기간까지 유효한지, 같은 ID에 다른 내용이 오면 어떻게 거부할지 계약을 정한다.\n\n## 금액 표현의 기본기\n\n십진 금액을 `double` 경유 값으로 만들면 기대한 소수와 다른 표현이 생길 수 있다. 입력 문자열에서 `BigDecimal`을 만들고 통화, 허용 자릿수, 반올림 규칙을 업무 정책으로 고정한다. `BigDecimal.equals`는 수치뿐 아니라 scale도 비교하므로 `1.0`과 `1.00`을 같은 업무 금액으로 볼지 별도 값으로 볼지 결정해야 한다. 비교 규칙을 고치면서 Map 키의 `hashCode`, DB 저장 표현, API 직렬화가 서로 다른 기준을 갖지 않게 한다.\n\n```java\nBigDecimal amount = new BigDecimal(request.amountText());\nBigDecimal normalized = amount.setScale(2, RoundingMode.UNNECESSARY);\n```\n\n위 코드는 소수 두 자리 초과를 거부하는 정책의 예다. 임의로 반올림해도 되는 업무라면 `UNNECESSARY` 대신 합의한 반올림 방식을 쓰고 경계값 테스트를 만든다. 통화별 자릿수가 같다고 가정하지 않는다.\n\n## 저장과 재시도\n\n요청 ID에 유일 제약을 두고, 처리 상태·원래 입력·결과를 같은 DB 작업으로 남기는 방식을 검토한다. 동시 요청 두 개가 먼저 조회했을 때 모두 ‘없다’고 판단할 수 있으므로 조회만으로 중복을 막지 않는다. 동일 ID 재시도에는 이전 결과를 반환할지 처리 중 상태를 반환할지 정의한다. 외부 연계 성공 뒤 로컬 저장이 실패하는 경우는 별도의 확인·재처리 경로가 필요하다. 테스트에는 동일 ID 동일 입력, 동일 ID 다른 입력, 서로 다른 ID 같은 금액, 동시 요청, 저장 실패를 넣는다. 이 예시는 일반적 소프트웨어 설계 사례이며 특정 금융기관의 실제 업무 규칙을 대신하지 않는다.","questions":[{"prompt":"같은 사용자가 같은 금액을 두 번 조정할 수 있다. 현재 `(userId, amount)`로 중복을 막아 정상 두 번째 요청도 거부됐다. 수정 방향은?","choices":["금액을 double로 바꿔 비교한다.","모든 중복 검사를 삭제한다.","논리 요청 ID를 계약으로 정의하고 같은 ID의 재시도와 새 요청을 구분한다.","시간이 같으면 같은 요청으로 취급한다."],"answer":3,"explanation":"금액이 같은 두 업무 요청은 별개일 수 있다. 요청 식별자를 명시해야 재전송과 새로운 요청을 구분할 수 있다."},{"prompt":"금액 `1.0`과 `1.00`을 업무상 같게 보지만 값 객체의 기본 equals는 다르다. 캐시 키와 DB 표현까지 고려한 대응은?","choices":["compareTo만 사용하고 hashCode는 그대로 둔다.","통화와 scale 정규화 정책을 정해 동등성·해시·저장 표현을 일치시킨다.","통화를 무시하고 문자열만 비교한다.","항상 double로 변환한다."],"answer":2,"explanation":"BigDecimal의 scale 차이와 값 객체 계약을 함께 다뤄야 한다. 비교만 바꾸면 해시 기반 조회나 저장 표현이 불일치할 수 있다."},{"prompt":"동시 요청 두 개가 모두 ‘요청 ID 없음’을 읽고 금액 변경을 시도한다. 중복 반영을 막기 위한 저장 경계는?","choices":["요청 ID에 저장소 유일 제약을 두고 상태 변경과 처리 결과를 원자적으로 기록한다.","두 조회 사이에 짧은 sleep을 넣는다.","화면 버튼을 비활성화하면 서버 검사는 생략한다.","금액의 소수 자릿수만 검사한다."],"answer":1,"explanation":"선조회만으로 동시 요청을 직렬화할 수 없다. 저장소 제약과 원자적 기록으로 같은 ID의 중복 반영을 막는다."}],"digest":"8899a716eba85e765849c4129e37eb8199456302af1f61dc2170108c5295e0d8"},{"slug":"interview-change-story","subject":"INTERVIEW","subjectName":"기술 면접","title":"유지보수 경험을 근거로 설명하기","objective":"변경 요구와 장애 대응 사례에서 자신의 판단·검증·결과를 구분해 설명한다.","keyPoints":["상황과 본인의 책임 범위를 구분한다.","선택한 방법과 버린 대안의 이유를 설명한다.","결과 수치가 없으면 관찰한 증거와 한계를 말한다."],"sources":[{"title":"Spring Framework Transaction Propagation","url":"https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/tx-propagation.html"},{"title":"PostgreSQL 17 Using EXPLAIN","url":"https://www.postgresql.org/docs/17/using-explain.html"}],"body":"# 8년차 SI 개발자의 변경 사례 설명\n\n면접에서 ‘기존 서비스의 어려운 변경을 설명해 달라’는 질문을 받았다. 기술 이름을 길게 나열하기보다 요구사항, 기존 제약, 자신의 역할, 선택, 검증, 결과를 연결한다. 예를 들어 배치에 새 상태 코드가 추가되었고 화면과 외부 파일 모두 그 코드를 처리해야 했다면, 무엇이 바뀌었고 어떤 경로를 직접 수정했는지 분명히 한다. 팀 전체 성과를 자신의 단독 성과처럼 말하지 않는다.\n\n## 답변의 중심\n\n상황: 어떤 업무 규칙이 바뀌었는가. 제약: 기존 데이터·호환성·배포 일정 중 무엇이 어려웠는가. 행동: 영향 범위를 어떻게 찾고 어떤 순서로 수정했는가. 검증: 어떤 테스트 데이터와 실패 사례로 확인했는가. 결과: 실제로 확인한 현상과 아직 측정하지 못한 것을 구분한다. 이 구조는 암기용 문장이 아니라 후속 질문에서 근거를 다시 꺼내기 위한 메모다.\n\n```text\n요구: 취소 상태를 배치 결과와 조회 화면에 함께 반영\n제약: 오래된 파일에는 새 상태 값이 없음\n선택: 상태 변환을 한 경계에 모으고 구버전 입력 테스트 유지\n검증: 이전 파일, 새 파일, 중복 행, 재실행 사례 확인\n결과: 검증 환경의 불일치 2건 수정; 운영 장기 효과는 미측정\n```\n\n위 수치는 설명 형식의 예시다. 실제 면접에서는 자신의 기록에 있는 수치만 사용한다. ‘성능을 개선했다’면 전후 조건과 측정 방법을 말하고, 측정하지 않았다면 ‘불필요한 반복 조회를 줄였고 실행 시간은 따로 측정하지 못했다’처럼 한계를 분명히 한다.\n\n## 실무 기본기를 묻는 꼬리 질문\n\n면접관이 ‘왜 트랜잭션 범위를 그렇게 잡았나’ 또는 ‘왜 JOIN 결과가 늘었나’를 물으면 용어 정의부터 외우지 않는다. 어떤 데이터가 함께 저장되어야 했는지, 누락·중복 행을 어떤 작은 데이터로 재현했는지 설명한다. 다른 대안을 버린 이유도 한 가지는 준비한다. 예를 들어 모든 원격 호출을 DB 트랜잭션 안에 넣는 방식은 지연·부분 실패를 검토해야 했고, `DISTINCT`만 추가하는 방식은 대표 행 규칙을 해결하지 못했다. 모르는 부분은 추측하지 말고 확인할 로그·테스트·문서를 제시한다. 연습 답변을 녹음해 2분 안에 핵심이 전달되는지 검토한다.","questions":[{"prompt":"면접에서 ‘배치 변경으로 성능을 개선했다’고 말하려는데 전후 실행 시간은 측정하지 않았다. 가장 신뢰할 만한 설명은?","choices":["개선율을 추정해 숫자로 단정한다.","측정하지 않은 시간 효과는 주장하지 않고 변경 내용과 확인한 결과를 분리해 말한다.","사용한 라이브러리 이름만 반복한다.","팀 전체의 지표를 자신의 단독 결과로 말한다."],"answer":2,"explanation":"확인한 사실과 추정은 구분해야 한다. 변경과 검증 증거를 말하되 측정하지 않은 성능 수치를 만들어 내지 않는다."},{"prompt":"‘JOIN을 고쳐 화면 중복을 해결했다’는 경험에 대한 꼬리 질문으로 가장 좋은 준비는?","choices":["SELECT 문법 정의만 외운다.","DISTINCT를 넣었다고만 답한다.","기준 행, 1:N 관계, 재현 데이터, 대표 행 선택 규칙과 회귀 테스트를 설명한다.","데이터 양이 적으니 문제없었다고 답한다."],"answer":3,"explanation":"경험의 신뢰도는 원인과 수정 근거, 검증 방법에서 나온다. DISTINCT만으로 업무상 대표 행 규칙을 설명할 수 없다."},{"prompt":"팀이 진행한 기능 변경을 설명할 때 자신의 기여를 명확히 하는 방법은?","choices":["요구와 팀의 결정, 본인이 수정·검증한 범위, 확인된 결과를 구분한다.","모든 설계와 구현을 혼자 했다고 말한다.","자신의 역할을 빼고 사용 기술만 나열한다.","후속 질문을 피하도록 결과만 짧게 말한다."],"answer":1,"explanation":"역할 경계를 구분하면 후속 질문에서 실제 판단과 검증을 구체적으로 설명할 수 있다."}],"digest":"4eada59ed7bcc2208bf9de606809530698e61a260ee2121ad1b799623a2478b3"}]'::jsonb) LOOP
        lesson_no := lesson_no + 1;
        INSERT INTO daily_career.subject(code,name) VALUES (lesson->>'subject',lesson->>'subjectName')
            ON CONFLICT (code) DO NOTHING;
        SELECT id INTO STRICT subject_id FROM daily_career.subject WHERE code=lesson->>'subject';
        INSERT INTO daily_career.learning_content(subject_id,title)
            VALUES (subject_id,lesson->>'title') RETURNING id INTO content_id;
        INSERT INTO daily_career.learning_content_version
            (learning_content_id,version_no,status,body_markdown,source_references,content_digest)
            VALUES (content_id,1,'DRAFT',lesson->>'body',lesson->'sources',lesson->>'digest')
            RETURNING id INTO content_version_id;
        INSERT INTO daily_career.learning_content_detail
            (content_version_id,title,learning_objective,key_points,interview_points)
            VALUES (content_version_id,lesson->>'title',lesson->>'objective',lesson->'keyPoints','[]'::jsonb);
        question_no := 0;
        FOR question IN SELECT value FROM jsonb_array_elements(lesson->'questions') LOOP
            question_no := question_no + 1;
            INSERT INTO daily_career.problem(subject_id,title)
                VALUES (subject_id,(lesson->>'title') || ' · 확인 ' || question_no)
                RETURNING id INTO problem_id;
            INSERT INTO daily_career.problem_version
                (problem_id,version_no,status,question_type,difficulty,prompt_markdown,choices,
                 answer_key,rubric,explanation_markdown,grading_rule_version,published_at)
                SELECT problem_id,1,'PUBLISHED','SINGLE_CHOICE',4,question->>'prompt',
                    (SELECT jsonb_agg(jsonb_build_object('id',ordinality::text,'text',value) ORDER BY ordinality)
                     FROM jsonb_array_elements_text(question->'choices') WITH ORDINALITY),
                    jsonb_build_object('correct',(question->>'answer')),'{}'::jsonb,
                    question->>'explanation','rule-choice-v1',clock_timestamp()
                RETURNING id INTO problem_version_id;
            INSERT INTO daily_career.learning_content_problem(content_version_id,problem_version_id,sequence)
                VALUES (content_version_id,problem_version_id,question_no);
        END LOOP;
        UPDATE daily_career.learning_content_version
            SET status='PUBLISHED',published_at=clock_timestamp(),updated_at=clock_timestamp(),revision=revision+1
            WHERE id=content_version_id;
        INSERT INTO daily_career.extra_learning_catalog(slug,content_version_id,display_order)
            VALUES (lesson->>'slug',content_version_id,lesson_no);
    END LOOP;
END
$extra_catalog$;
